82	        Map<String, Object> data = new LinkedHashMap<>();
83	        data.put("id", provider.getId());
84	        data.put("name", provider.getName());
85	        data.put("baseUrl", provider.getBaseUrl());
86	        data.put("modelId", provider.getModelId());
87	        data.put("status", provider.getStatus());
88	        data.put("errorMessage", provider.getErrorMessage());
89	        data.put("lastValidatedAt", provider.getLastValidatedAt() != null ? provider.getLastValidatedAt().toString() : null);
90	        data.put("createdAt", provider.getCreatedAt() != null ? provider.getCreatedAt().toString() : null);
91	        return ResponseEntity.ok(ApiResponse.success("success", data));
92	    }
