import com.modelgate.platform.service.ProviderService;
import java.lang.reflect.Method;

public class HelperTest {
    public static void main(String[] args) throws Exception {
        ProviderService svc = new ProviderService();
        Method get = ProviderService.class.getDeclaredMethod("sendGetRequest", String.class, String.class);
        Method post = ProviderService.class.getDeclaredMethod("sendPostRequest", String.class, String.class, String.class);
        get.setAccessible(true);
        post.setAccessible(true);

        String base = "http://127.0.0.1:18081";
        int[][] getCases = {{200, 200}, {401, 401}, {404, 404}, {500, 500}};
        for (int[] c : getCases) {
            int got = (int) get.invoke(svc, base + "/status/" + c[0], "k1");
            System.out.println("GET " + c[0] + " -> " + got);
            if (got != c[1]) throw new AssertionError("GET mismatch");
        }
        int drop = (int) get.invoke(svc, base + "/drop", "k1");
        System.out.println("GET drop -> " + drop);
        if (drop != -1) throw new AssertionError("GET drop should be -1");
        int refused = (int) get.invoke(svc, "http://127.0.0.1:1/x", "k1");
        System.out.println("GET refused -> " + refused);
        if (refused != -1) throw new AssertionError("refused should be -1");
        int bad = (int) get.invoke(svc, "not a url", "k1");
        System.out.println("GET malformed -> " + bad);
        if (bad != -1) throw new AssertionError("malformed should be -1");

        String body = "{\"model\":\"m1\",\"messages\":[{\"role\":\"user\",\"content\":\"ping\"}],\"max_tokens\":1}";
        int ok = (int) post.invoke(svc, base + "/status/200", "secret", body);
        System.out.println("POST 200 -> " + ok);
        if (ok != 200) throw new AssertionError("POST mismatch");
        int p401 = (int) post.invoke(svc, base + "/status/401", "secret", body);
        System.out.println("POST 401 -> " + p401);
        if (p401 != 401) throw new AssertionError("POST 401 mismatch");
        int pdrop = (int) post.invoke(svc, base + "/drop", "secret", body);
        System.out.println("POST drop -> " + pdrop);
        if (pdrop != -1) throw new AssertionError("POST drop should be -1");

        System.out.println("HELPERS OK");
    }
}

