import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class BranchTest {
    static int updates;
    static ModelProvider lastUpdated;

    static class FakeUserMapper implements UserMapper {
        public User findByUsername(String u) { return User.builder().id(1L).username(u).build(); }
        public User findById(Long id) { return null; }
        public void insert(User u) { }
        public int count() { return 1; }
    }

    static class FakeProviderMapper implements ModelProviderMapper {
        Map<Long, ModelProvider> data = new HashMap<>();
        public ModelProvider findById(Long id) { return data.get(id); }
        public List<ModelProvider> findByUserId(Long uid) { return new ArrayList<>(); }
        public void insert(ModelProvider p) { data.put(p.getId(), p); }
        public void update(ModelProvider p) {
            updates++;
            lastUpdated = ModelProvider.builder()
                    .id(p.getId()).userId(p.getUserId()).name(p.getName())
                    .baseUrl(p.getBaseUrl()).apiKey(p.getApiKey()).modelId(p.getModelId())
                    .status(p.getStatus()).errorMessage(p.getErrorMessage())
                    .lastValidatedAt(p.getLastValidatedAt()).createdAt(p.getCreatedAt())
                    .build();
        }
    }

    static ProviderService svc;

