import com.modelgate.platform.entity.ModelProvider;
import com.modelgate.platform.entity.User;
import com.modelgate.platform.mapper.ModelProviderMapper;
import com.modelgate.platform.mapper.UserMapper;
import com.modelgate.platform.service.ProviderService;

import java.lang.reflect.Field;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class BranchTest {
    static int updates;
    static ModelProvider lastUpdated;

    static class FakeUserMapper implements UserMapper {
        public User findByUsername(String u) { return User.builder().id(1L).username(u).build(); }
        public User findById(Long id) { return null; }
        public void insert(User u) { }
        public int count() { return 1; }
    }

    static class FakeProviderMapper implements ModelProviderMapper {
        Map<Long, ModelProvider> data = new HashMap<>();
        public ModelProvider findById(Long id) { return data.get(id); }
        public List<ModelProvider> findByUserId(Long uid) { return new ArrayList<>(); }
        public void insert(ModelProvider p) { data.put(p.getId(), p); }
        public void update(ModelProvider p) {
            updates++;
            lastUpdated = ModelProvider.builder()
                    .id(p.getId()).userId(p.getUserId()).name(p.getName())
                    .baseUrl(p.getBaseUrl()).apiKey(p.getApiKey()).modelId(p.getModelId())
                    .status(p.getStatus()).errorMessage(p.getErrorMessage())
                    .lastValidatedAt(p.getLastValidatedAt()).createdAt(p.getCreatedAt())
                    .build();
        }
    }

    static ProviderService svc;

    public static void main(String[] args) throws Exception {
        FakeProviderMapper pm = new FakeProviderMapper();
        svc = new ProviderService();
        Field f = ProviderService.class.getDeclaredField("modelProviderMapper");
        f.setAccessible(true);
        f.set(svc, pm);
        Field g = ProviderService.class.getDeclaredField("userMapper");
        g.setAccessible(true);
        g.set(svc, new FakeUserMapper());

        // Exhaustive branch matrix
        check(pm, 200, 200, "VALID", null, 0);
        check(pm, 401, 200, "INVALID", "API key is invalid (HTTP 401)", 0);
        check(pm, 403, 200, "INVALID", "API key is invalid (HTTP 403)", 0);
        check(pm, 500, 200, "VALID", null, 0);
        check(pm, 404, 200, "VALID", null, 1);
        check(pm, 404, 401, "INVALID", "API key is invalid (HTTP 401)", 1);
        check(pm, 404, 403, "INVALID", "API key is invalid (HTTP 403)", 1);
        check(pm, 404, 500, "VALID", null, 1);
        check(pm, -1, 200, "VALID", null, 1);
        check(pm, -1, -1, "ERROR", "Connection failed", 1);
        check(pm, 404, -1, "ERROR", "Connection failed", 1);

        // Re-validation overwrites prior outcome
        ModelProvider p = provider(50L, 1L);
        pm.data.put(50L, p);
        control("get", 401);
        updates = 0;
        ModelProvider r1 = svc.validateProvider(50L, "alice");
        assertEq("reval-1", "INVALID", r1.getStatus());
        assertEq("reval-msg-1", "API key is invalid (HTTP 401)", r1.getErrorMessage());
        control("get", 200);
        ModelProvider r2 = svc.validateProvider(50L, "alice");
        assertEq("reval-2", "VALID", r2.getStatus());
        assertEq("reval-msg-2", null, r2.getErrorMessage());
        if (updates != 2) throw new AssertionError("expected 2 updates, got " + updates);
        if (r2.getLastValidatedAt() == null) throw new AssertionError("timestamp missing");

        // Nonexistent provider -> null, no write
        updates = 0;
        if (svc.validateProvider(9999L, "alice") != null) throw new AssertionError("missing should be null");
        if (updates != 0) throw new AssertionError("no write expected for missing provider");

        // Wrong owner -> null, no write
        ModelProvider other = provider(60L, 2L);
        pm.data.put(60L, other);
        updates = 0;
        if (svc.validateProvider(60L, "alice") != null) throw new AssertionError("wrong owner should be null");
        if (updates != 0) throw new AssertionError("no write expected for wrong owner");

        // Persisted entity carries status/error/timestamp (what mapper.update receives)
        control("get", 401);
        pm.data.put(70L, provider(70L, 1L));
        svc.validateProvider(70L, "alice");
        assertEq("persist-status", "INVALID", lastUpdated.getStatus());
        assertEq("persist-msg", "API key is invalid (HTTP 401)", lastUpdated.getErrorMessage());
        if (lastUpdated.getLastValidatedAt() == null) throw new AssertionError("persisted timestamp missing");

        System.out.println("BRANCHES OK");
    }

    static ModelProvider provider(long id, long userId) {
        return ModelProvider.builder().id(id).userId(userId).name("p")
                .baseUrl("http://127.0.0.1:18082").apiKey("k").modelId("m1")
                .status("PENDING").build();
    }

    static void check(FakeProviderMapper pm, int getCode, int postCode,
                      String status, String msg, int postCount) throws Exception {
        control("get", getCode);
        control("post", postCode);
        int before = postCount();
        ModelProvider p = provider(1L, 1L);
        pm.data.put(1L, p);
        updates = 0;
        ModelProvider r = svc.validateProvider(1L, "alice");
        if (r == null) throw new AssertionError("unexpected null");
        assertEq("status(g=" + getCode + ",p=" + postCode + ")", status, r.getStatus());
        assertEq("msg(g=" + getCode + ",p=" + postCode + ")", msg, r.getErrorMessage());
        if (r.getLastValidatedAt() == null) throw new AssertionError("timestamp missing");
        if (updates != 1) throw new AssertionError("expected one update, got " + updates);
        int actualPosts = postCount() - before;
        if (actualPosts != postCount)
            throw new AssertionError("post count expected " + postCount + " got " + actualPosts);
        if (postCount > 0) {
            String st = new String(Files.readAllBytes(Paths.get("/tmp/mock_state.json")));
            if (!st.contains("\"last_auth\": \"Bearer k\""))
                throw new AssertionError("missing bearer header: " + st);
            if (!st.contains("\"last_ctype\": \"application/json\""))
                throw new AssertionError("missing content type: " + st);
            if (!st.contains("\\\"model\\\":\\\"m1\\\"") || !st.contains("\\\"max_tokens\\\":1")
                    || !st.contains("\\\"role\\\":\\\"user\\\""))
                throw new AssertionError("bad probe body: " + st);
        }
        System.out.println("g=" + getCode + " p=" + postCode + " -> " + r.getStatus()
                + " msg=" + r.getErrorMessage() + " posts=" + actualPosts);
    }

    static void control(String which, int code) throws Exception {
        new URL("http://127.0.0.1:18082/control/" + which + "/" + code).openStream().close();
    }

    static int postCount() throws Exception {
        String st = new String(Files.readAllBytes(Paths.get("/tmp/mock_state.json")));
        Matcher m = Pattern.compile("\"post_count\": (\\d+)").matcher(st);
        if (!m.find()) throw new AssertionError("no state file");
        return Integer.parseInt(m.group(1));
    }

    static void assertEq(String what, Object expected, Object actual) {
        if (!Objects.equals(expected, actual))
            throw new AssertionError(what + ": expected <" + expected + "> got <" + actual + ">");
    }
}

